def boundedScalarReader (η : ℝ → ℝ) (hη : StronglyMeasurable η)
    (hb : ∀ x, ‖η x‖ ≤ 1) : Lp ℝ p unitIntervalMeasure →L[ℝ] ℝ :=
  (probabilityLpIntegral (𝕜 := ℝ)).comp (boundedMultiply η hη hb)

